function SeparateParenGroups(parenString: string): array of string;
begin
  var groups := new List<string>;
  var stack := new Stack<char>;
  var currentGroup := '';

  for var i := 1 to parenString.Length do
  begin
    var c := parenString[i];

    if c = ' ' then
      continue
    else if c = '(' then
    begin
      stack.Push(c);
      currentGroup += '(';
    end
    else if c = ')' then
    begin
      currentGroup += ')';
      stack.Pop;

      if stack.Count = 0 then
      begin
        groups.Add(currentGroup);
        currentGroup := '';
      end;
    end;
  end;

  Result := groups.ToArray;
end;

begin
end.




