function ParseNestedParens(parenString: string): array of integer;
begin
  var levelStack := new Stack<integer>;
  var maxLevelStack := new Stack<integer>;
  levelStack.Push(0);
  maxLevelStack.Push(0);
  var maxLevel := 0;
  var currentLevel := 0;
  var maxLevelForCurrentGroup := 0;
  var currentGroup := 0;
  var start := 1;
  for var i := 1 to parenString.Length do
  begin
    if parenString[i] = ' ' then
    begin
      currentGroup += 1;
      start := i + 1;
    end;
    if parenString[i] = '(' then
    begin
      currentLevel += 1;
      if currentLevel > maxLevelForCurrentGroup then
        maxLevelForCurrentGroup := currentLevel;
      levelStack.Push(currentLevel);
      maxLevelStack.Push(maxLevelForCurrentGroup);
    end
    else if parenString[i] = ')' then
    begin
      currentLevel -= 1;
      if currentLevel = maxLevelForCurrentGroup then
        maxLevelForCurrentGroup := maxLevelStack.Pop;
    end;
  end;
  Result := levelStack.ToArray;
end;

begin
end.




