function MakePalindrome(str : string): string;
{ Find the shortest palindrome that begins with a supplied string.
    Algorithm idea is simple:
    - Find the longest postfix of supplied string that is a palindrome.
    - Append to the end of the string reverse of a string prefix that comes before the palindromic suffix.
    >>> MakePalindrome('')
    ''
    >>> MakePalindrome('cat')
    'catac'
    >>> MakePalindrome('cata')
    'catac' }

```pascal
function IsPalindrome(s: string): boolean;
begin
  var reversed := '';
  for var i := s.Length downto 1 do
    reversed += s[i];
  Result := s = reversed;
end;

function MakePalindrome(str: string): string;
begin
  if str = '' then
  begin
    Result := '';
    exit;
  end;

  var reversed := '';
  for var i := str.Length downto 1 do
    reversed += str[i];

  for var i := reversed.Length - 1 downto 0 do
  begin
    var prefix := reversed.Substring(0, i);
    if IsPalindrome(prefix) then
    begin
      Result := str + ReverseString(reversed.Substring(i));
      exit;
    end;
  end;

  Result := str + ReverseString(reversed);
end;
