function ChangeBase(x: integer; base: integer): string;
begin
  if (x = 0) or (base = 0) then
  begin
    Result := '';
    exit;
  end;

  var digits := new List<char>;
  var num := x;

  while num > 0 do
  begin
    digits.Add(Chr(num mod 10 + 48));
    num := num div 10;
  end;

  if base < 10 then
  begin
    digits.Reverse;
    Result := string.Join('', digits);
  end
  else
  begin
    digits.Reverse;
    Result := string.Join('', digits.Select(c -> if (c >= '0') and (c <= '9') then c else Chr(base - 10 + 48)));
  end;
end;

begin
end.




