  for var i := 0 to s0.Length - 1 do
  begin
    if s0Dict.ContainsKey(s0[i]) then
      s0Dict[s0[i]] += 1
    else
      s0Dict[s0[i]] := 1;
  end;

  for var i := 0 to s1.Length - 1 do
  begin
    if s1Dict.ContainsKey(s1[i]) then
      s1Dict[s1[i]] += 1
    else
      s1Dict[s1[i]] := 1;
  end;

  foreach var kv in s0Dict do
  begin
    if not s1Dict.ContainsKey(kv.Key) or (s1Dict[kv.Key] <> kv.Value) then
    begin
      Result := false;
      exit;
    end;
  end;

  Result := true;
end;

