    for var j := i + 1 to n - 1 do
    begin
      if arr[i] = arr[j] then
        dp[i, j] := dp[i + 1, j - 1]
      else
        dp[i, j] := Min(dp[i + 1, j], dp[i, j - 1]) + 1;
