function MaxFill(grid: array of array of integer; capacity: integer): integer;
begin
  var m := grid.Length;
  var n := grid[0].Length;
  var res := 0;
  var buckets := new integer[m * n];

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
        buckets[i * n + j] := capacity;

  for var i := 0 to m - 1 do
    for var j := 0 to n - 1 do
      if grid[i][j] = 1 then
      begin
        var x := i div n;
        var y := i mod n;
        var bucket := x * n + y;
        buckets[bucket] -= 1;
        res += 1;
      end;

  Result := res;
end;

begin
end.




