function Minpath(grid: array of array of integer; k: integer): array of integer;
begin
  var n := grid.Length;
  var res := new integer[k];
  var directions := |(0, 1), (1, 0), (0, -1), (-1, 0)|;
  var visited := new boolean[n * n];
  var queue := new Queue<(integer, integer, integer)>;
  queue.Enqueue((grid[0][0], 0, 0));

  while queue.Count > 0 do
  begin
    var (x, y, step) := queue.Dequeue;
    if step = k - 1 then
    begin
      res[0] := grid[x][y];
      break;
    end;

    foreach var (dx, dy) in directions do
    begin
      var nx := x + dx;
      var ny := y + dy;
      if (nx >= 0) and (nx < n) and (ny >= 0) and (ny < n) and not visited[nx * n + ny] then
      begin
        visited[nx * n + ny] := true;
        queue.Enqueue((nx, ny, step + 1));
      end;
    end;
  end;

  Result := res;
end;

begin
end.




